   24				var oe observe.Event
   25				if json.Unmarshal(v, &oe) == nil {
   26					attribution.observe(&oe)
   27				}
   28			}
   29			for k, v := c.Last(); k != nil; k, v = c.Prev() {
   30				var oe observe.Event
   31				if err := json.Unmarshal(v, &oe); err != nil {
   32					continue
   33				}
   34				oe = *attribution.project(&oe)
   35				if !since.IsZero() && oe.Timestamp.Before(since) {
   36					continue
   37				}
   38				if !until.IsZero() && oe.Timestamp.After(until) {
   39					continue
   40				}
